        "settings.about" to mapOf("en" to "About", "zh-Hans" to "关于", "zh-Hant" to "關於", "ja" to "このアプリについて", "ko" to "정보", "vi" to "Giới thiệu", "es" to "Acerca de", "fr" to "À propos", "de" to "Über", "ru" to "О приложении", "ar" to "حول"),
